    $('.compose').onsubmit=e=>{e.preventDefault();if(input.value.trim())submit(input.value.trim());};input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('.compose').requestSubmit();}};
