    $('.new-chat').onclick=()=>{token='';storage.set('');thread=null;requestId='';clearError();welcome();tab('chat');};$('.retry').onclick=()=>errorKind==='load'?load():refresh();
    const keydown=e=>{if(e.key==='Escape'&&!panel.hidden)hide();};shadow.addEventListener('keydown',keydown);
    const pageshow=()=>{startPolling();if(!panel.hidden)refresh();};const pagehide=()=>clearInterval(poll);const visibility=()=>{if(!document.hidden&&!panel.hidden)refresh();};const mediaChange=()=>apply(settings);
    window.addEventListener('pageshow',pageshow);window.addEventListener('pagehide',pagehide);document.addEventListener('visibilitychange',visibility);media.addEventListener('change',mediaChange);
    const api={open:show,close:hide,update(c){if(preview){apply(c);}},destroy(){disposed=true;clearInterval(poll);window.removeEventListener('pageshow',pageshow);window.removeEventListener('pagehide',pagehide);document.removeEventListener('visibilitychange',visibility);media.removeEventListener('change',mediaChange);host.remove();instances.delete(key);}};instances.set(key,api);
    if(preview){ready=true;apply(config||{});emit('ready',{preview:true});}else load();if(open)show();return api;
